{"tiddlers":{"$:/themes/huwiki/modern/base":{"title":"$:/themes/huwiki/modern/base","text":"/* HUWiki Modern v0.1.2 · CSS only · Vanilla-dependent theme · palette-aware */
:root { --hu-radius: var(--hu-modern-corners,17px); --hu-accent: var(--tpc-primary, #315cf5); }
html body.tc-body {
  font-family: var(--tp-font-family, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif);
  -webkit-font-smoothing: antialiased;
  letter-spacing: -0.009em;
  background: var(--tpc-page-background, #f3f6fb);
  color: var(--tpc-foreground, #17253b);
}
.tc-story-river { padding-bottom: 5rem; }
.tc-tiddler-frame {
  border-radius: var(--hu-radius) !important;
  border: 1px solid var(--tpc-tab-border, #dce5f4);
  box-shadow: 0 12px 34px -25px rgba(29, 52, 91, .34), 0 2px 6px -4px rgba(29,52,91,.2);
  background: var(--tpc-tiddler-background, #fff);
  transition: box-shadow .18s ease, border-color .18s ease;
}
.tc-tiddler-frame:hover { border-color: var(--tpc-button-border, #c4d0e6); box-shadow:0 16px 40px -25px rgba(29,52,91,.42); }
.tc-tiddler-title { font-size: 1.46em; font-weight: 745; letter-spacing: -.045em; line-height:1.2; }
.tc-titlebar { padding-bottom: .7em; }
.tc-titlebar h2.tc-title { font-size: 1.28em; font-weight:760; letter-spacing:-.038em; line-height:1.22; overflow-wrap:break-word; }
.tc-tiddler-subtitle { letter-spacing: .015em; opacity:.85; }
.tc-tiddler-body { line-height: var(--tp-body-line-height,1.65); font-size: 1.035em; }
.tc-tiddler-body h1,.tc-tiddler-body h2,.tc-tiddler-body h3,
.tc-tiddler-body h4 { font-family: inherit; letter-spacing:-.028em; line-height:1.3; font-weight:720; }
.tc-tiddler-body h1 {font-size:1.9em}
.tc-tiddler-body h2 {font-size:1.5em}
.tc-tiddler-body h3 {font-size:1.2em}
.tc-tiddler-body blockquote { border-left:4px solid var(--hu-accent); padding:.35em 1.1em; margin:1.2em 0; border-radius:0 9px 9px 0; }
.tc-sidebar-header { padding: 1em .6em 1.3em; }
.tc-site-title { font-weight: 780; letter-spacing:-.045em; line-height:1.2; font-size: 2em; }
.tc-site-subtitle { font-size:.86em; line-height:1.45; opacity:.85; }
.tc-sidebar-lists { font-size:.92em; }
.tc-sidebar-tabs .tc-tab-buttons { border-radius:11px; padding:5px; background:var(--tpc-sidebar-tab-background, #eaf0fa); }
.tc-sidebar-tabs .tc-tab-buttons button { border-radius:8px; margin:1px; padding: .45em .65em; }
.tc-sidebar-tabs .tc-tab-buttons button.tc-tab-selected { background:var(--tpc-sidebar-tab-background-selected,#fff); box-shadow:0 1px 5px #10243e22; }
.tc-search input { border:1px solid var(--tpc-button-border, #d4deef); background:var(--tpc-tiddler-background,#fff); border-radius:10px; padding:.65em .85em; min-height:2.3em; }
.tc-search input:focus { outline:2px solid var(--hu-accent); outline-offset:2px; }
.tc-tiddler-controls button, .tc-page-controls button { border-radius:8px; transition:background .14s ease, transform .14s ease; }
.tc-tiddler-controls button:hover,.tc-page-controls button:hover { background:var(--tpc-button-background,#f5f7fd); }
.tc-tiddler-controls button:focus-visible,.tc-page-controls button:focus-visible, button:focus-visible,a:focus-visible { outline:2px solid var(--hu-accent); outline-offset:3px; }
.tc-tags-wrapper .tc-tag-list-item { border-radius: 999px; }
.tc-drop-down, .tc-block-dropdown, .tc-modal { border-radius:12px; }
.tc-tiddler-body table { border-collapse:separate; border-spacing:0; overflow:hidden; border-radius:9px; }
.tc-tiddler-body pre,.tc-tiddler-body code { border-radius:7px; }
.tc-edit-texteditor,.tc-edit-texteditor-body { border-radius: 10px; }
@media (max-width: 720px) {
  .tc-tiddler-frame { border-radius:var(--hu-radius) !important; margin-bottom:1em; }
  .tc-tiddler-title {font-size:1em}
  .tc-titlebar h2.tc-title {font-size:1.09em;line-height:1.25}
  .tc-tiddler-body {font-size:1em}
  .tc-sidebar-header {padding:.7em .5em}
}
@media (prefers-reduced-motion:reduce) {
  .tc-tiddler-frame,.tc-tiddler-controls button,.tc-page-controls button {transition:none!important;}
}
@media print {
  .tc-tiddler-frame { border:0!important; border-radius:0!important; box-shadow:none!important; }
  html body.tc-body {background:#fff;color:#111}
}

/* iPadOS / WebKit: keep sidebar search focus from magnifying the visual viewport.
   Limit this workaround to touch WebKit and the search input. Do not override
   TiddlyWiki's native sidebar layout, scroll handling or page zoom. */
@supports (-webkit-touch-callout: none) {
  .tc-search input {
    font-size: 16px !important;
    min-height: 30px;
    padding: 4px 8px;
    line-height: 1.3;
  }
  .tc-search input:focus {
    outline-offset: -2px;
  }
}
